import{_ as e,o as r,c as a,a5 as n}from"./chunks/framework.QWVCgkrI.js";const o="/study/images/network/home-network-devices.svg",p=JSON.parse('{"title":"家庭のネットワーク機器 — LAN・ルーター・Wi-Fiの役割","description":"","frontmatter":{"title":"家庭のネットワーク機器 — LAN・ルーター・Wi-Fiの役割","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"network","summary":"PCからインターネットへ届く経路を、NIC、スイッチ、Wi-Fiアクセスポイント、ルーター、ONUに分けて説明する。LANとWAN、DHCPとDNSの役割も整理する。","aliases":["LAN","WAN","NIC","Ethernet","Wi-Fi","スイッチ","ルーター","アクセスポイント","AP","ONU","モデム","DHCP","デフォルトゲートウェイ"],"verification":"Cisco・NTT・バッファローの機器解説と、IETFのDHCP・DNS・IPルーティング関連仕様に照合（2026-11-07）"}},"headers":[],"relativePath":"network/home-network-devices.md","filePath":"network/home-network-devices.md"}'),s={name:"network/home-network-devices.md"};function i(h,t,c,d,l,w){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="家庭のネットワーク機器-—-lan・ルーター・wi-fiの役割" tabindex="-1">家庭のネットワーク機器 — LAN・ルーター・Wi-Fiの役割 <a class="header-anchor" href="#家庭のネットワーク機器-—-lan・ルーター・wi-fiの役割" aria-label="Permalink to &quot;家庭のネットワーク機器 — LAN・ルーター・Wi-Fiの役割&quot;">​</a></h1><p>PCでオンラインゲームに接続すると、PC自身の通信機能に加え、家庭内の機器と回線を通ってサーバーへデータが向かいます。店頭で「Wi-Fiルーター」と呼ばれる一台の中にも、複数の役割が入っています。ここでは役割ごとに分けて、PCから家の外へ出るまでを追います。<a href="https://www.cisco.com/site/us/en/learn/topics/networking/what-is-computer-networking.html" target="_blank" rel="noreferrer">Ciscoのネットワーク機器の概要</a> · <a href="/study/network/network-basics.html">ネットワークの基礎</a></p><h2 id="lanとwan" tabindex="-1">LANとWAN <a class="header-anchor" href="#lanとwan" aria-label="Permalink to &quot;LANとWAN&quot;">​</a></h2><p><strong>LAN</strong>（Local Area Network）は、自宅やオフィスなど、限られた範囲の機器を結ぶネットワークです。有線の<strong>Ethernet</strong>でも、無線の<strong>Wi-Fi</strong>でもLANを構成できます。家庭用ルーターのLAN側には、PC、ゲーム機、スマートフォンなどがつながります。<a href="https://www.cisco.com/site/us/en/learn/topics/networking/what-is-computer-networking.html#types-of-computer-networks" target="_blank" rel="noreferrer">CiscoのLANの説明</a></p><p>WAN（Wide Area Network）は離れた場所のネットワークを広域に結びます。家庭用ルーターの「WAN」「Internet」と書かれた端子は、一般に回線事業者側へ接続するために使います。その先のインターネットでは、複数のネットワークやルーターを経由してデータを宛先へ転送します。<a href="https://www.cisco.com/site/us/en/learn/topics/networking/what-is-computer-networking.html" target="_blank" rel="noreferrer">CiscoのWANの説明</a> · <a href="/study/network/ip-routing-and-ethernet.html">IPルーティング</a></p><h2 id="家庭で出会う機器" tabindex="-1">家庭で出会う機器 <a class="header-anchor" href="#家庭で出会う機器" aria-label="Permalink to &quot;家庭で出会う機器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>機器・機能</th><th>主な仕事</th><th>家庭での例</th></tr></thead><tbody><tr><td><strong>NIC・ネットワークアダプター</strong></td><td>PCがネットワークにデータを出し入れする。</td><td>PCの有線LAN端子やWi-Fiアダプター。</td></tr><tr><td><strong>スイッチ</strong></td><td>同じLANの有線機器を結び、Ethernetの宛先MACアドレスを手がかりに転送する。</td><td>LAN端子を増やす機器、家庭用ルーター内のLAN端子部分。</td></tr><tr><td><strong>アクセスポイント（AP）</strong></td><td>Wi-Fi端末をLANにつなぐ。</td><td>ノートPCの無線通信を、LAN側へ橋渡しする部分。</td></tr><tr><td><strong>ルーター</strong></td><td>別々のIPネットワークの間で、宛先IPに応じて次の送り先を選ぶ。</td><td>家庭のLANと回線側のネットワークを結ぶ部分。</td></tr><tr><td><strong>ONU・光回線終端装置</strong></td><td>光回線の信号と、端末側で使う電気信号とのやり取りを担う。</td><td>光ファイバーを接続する回線終端の機器。</td></tr><tr><td><strong>モデム</strong></td><td>回線で使う信号の変調・復調を行う。方式は回線によって異なる。</td><td>電話線を使うDSLモデムや、ケーブル回線のモデム。</td></tr></tbody></table><p>Ethernetでは、同じリンクで届ける相手を示す<strong>MACアドレス</strong>と、IPネットワークで宛先を示す<strong>IPアドレス</strong>を使います。一般的なスイッチは前者を、ルーターの経路選択は後者を手がかりにします。機種によってはスイッチにルーティング機能も備わります。<a href="https://www.cisco.com/site/us/en/learn/topics/small-business/network-switch-vs-router.html" target="_blank" rel="noreferrer">Ciscoのスイッチとルーター</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/network/network-interface-card-support" target="_blank" rel="noreferrer">MicrosoftのNICの説明</a> · <a href="https://www.ntt.com/business/services/network/internet-connect/ocn-business/bocn/knowledge/archive_118.html" target="_blank" rel="noreferrer">NTTのONU・モデム・ルーターの解説</a></p><figure class="study-figure"><img src="'+o+'" alt="有線のPCはスイッチ、ルーター、ONUを経て回線事業者側へ進む。Wi-FiのPCはアクセスポイントからスイッチにつながる。家庭用Wi-Fiルーターではスイッチ・アクセスポイント・ルーターの三機能を一台にまとめた製品が多い。" width="760" height="420" loading="lazy"><figcaption>光回線を使う家庭の一例を、機能単位で描いています。ONUとルーターが一体の製品もあります。<a href="/study/images/network/home-network-devices.svg" target="_blank" rel="noopener noreferrer">家庭の接続図を拡大</a></figcaption></figure><h2 id="同じlanへの通信と、家の外への通信" tabindex="-1">同じLANへの通信と、家の外への通信 <a class="header-anchor" href="#同じlanへの通信と、家の外への通信" aria-label="Permalink to &quot;同じLANへの通信と、家の外への通信&quot;">​</a></h2><p>同じ<strong>IPサブネット</strong>（IPアドレスで区切るネットワークの範囲）内で直接届けられる相手なら、PCはその相手へLAN上で送ります。例えばPCから家庭内の別のPCへ送るデータは、同じスイッチで届く構成なら、そのスイッチ内を通れます。Wi-Fi端末ならアクセスポイントも通ります。ゲスト用Wi-Fiなどでは、設定によって端末同士の通信が制限される場合があります。<a href="/study/network/ip-routing-and-ethernet.html">IPルーティングとEthernet</a> · <a href="https://documentation.meraki.com/Wireless/Operate_and_Maintain/How_Tos/Firewall_and_Traffic_Shaping/Wireless_Client_Isolation" target="_blank" rel="noreferrer">Cisco Merakiの端末間通信の分離</a></p><p>外部のゲームサーバーへ送る場合、PCは通常、<strong>デフォルトゲートウェイ</strong>として設定されたルーターへ渡します。ルーターが回線側へ転送し、その先のルーターも次の送り先を選びます。IPv4の家庭用接続では、途中で内側のIPやポートを外側の値へ書き換えるNATが使われることがあります。<a href="https://www.rfc-editor.org/rfc/rfc1812.html#section-5.2.4" target="_blank" rel="noreferrer">IETF RFC 1812の経路選択</a> · <a href="/study/network/nat-and-port-mapping.html">NATとポート変換</a></p><p>家庭用のWi-Fiルーターは、スイッチ、アクセスポイント、ルーターの機能を一台にまとめた製品が多くあります。アクセスポイントとして使うモードでは、接続先の別ルーターが経路選択やアドレス配布を担当する構成にできます。一台の箱にまとまっていても、通信の流れはそれぞれの役割に分けて考えられます。<a href="https://www.buffalo.jp/support/faq/detail/290.html" target="_blank" rel="noreferrer">バッファローのAPモード</a> · <a href="https://www.ntt.com/business/services/network/internet-connect/ocn-business/bocn/knowledge/archive_118.html" target="_blank" rel="noreferrer">NTTの一体型ONU・ルーター</a></p><h2 id="ip設定を配るdhcpと、名前を調べるdns" tabindex="-1">IP設定を配るDHCPと、名前を調べるDNS <a class="header-anchor" href="#ip設定を配るdhcpと、名前を調べるdns" aria-label="Permalink to &quot;IP設定を配るDHCPと、名前を調べるDNS&quot;">​</a></h2><p><strong>DHCP</strong>は、端末がIPアドレスやネットワーク設定を受け取るための仕組みです。IPv4の家庭内LANでは、ルーター内のDHCPサーバーが、端末へ利用するアドレスやゲートウェイ、DNSサーバーの情報を配る構成がよく使われます。これらはルーティングとは別の機能で、別のサーバーで動かすこともできます。<a href="https://www.rfc-editor.org/rfc/rfc2131.html#section-1" target="_blank" rel="noreferrer">IETF RFC 2131のDHCP</a> · <a href="https://www.rfc-editor.org/rfc/rfc2132.html#section-3.5" target="_blank" rel="noreferrer">RFC 2132のルーターとDNSオプション</a></p><p><strong>DNS</strong>は、<code>example.com</code>のような名前からIPアドレスなどの情報を調べる仕組みです。家庭用ルーターがDNSの問い合わせを受け、別のDNSサーバーへ問い合わせる構成もあります。IPv6では、ルーターの通知によるアドレス設定やDHCPv6など、IPv4のDHCPとは異なる設定方法も使われます。<a href="https://www.rfc-editor.org/rfc/rfc1034.html#section-2" target="_blank" rel="noreferrer">IETF RFC 1034のDNS</a> · <a href="https://www.rfc-editor.org/rfc/rfc4862.html#section-5.5" target="_blank" rel="noreferrer">IPv6のアドレス自動設定</a> · <a href="/study/network/dns-resolution.html">DNSと名前解決</a></p><p>接続を調べるときは、PCのネットワークアダプター、接続先のLAN、ゲートウェイ、DNSの値を順に確認すると、どの機器やサービスを使っているか分かります。IPアドレスとポートの読み方は<a href="/study/network/ip-addresses-and-ports.html">IPアドレスとポート</a>、実際にNICがデータを受け取る仕組みは<a href="/study/hardware/io/nic-receive-queues.html">NICの受信キューとRSS</a>で扱います。</p>',17)])])}const g=e(s,[["render",i]]);export{p as __pageData,g as default};
